\title{Maximal Rank of Self-Dual String C-Groups for the Alternating Groups $A_{4m+3}$}
\author{Aristotle}
\date{2026-06-27}

\begin{document}

\begin{abstract}
String C-groups are the group-theoretic incarnation of abstract regular
polytopes: a group equipped with an ordered set of involutory generators
satisfying a string commuting condition and an intersection property. A
representation is \emph{self-dual} when an automorphism of the ambient group
reverses the order of the generators. We develop, from first principles, the
algebra of \emph{string group representations}, their \emph{period matrices}, and
their \emph{Schl\"afli symbols}, and we prove the \emph{palindrome theorem}: a
self-dual representation has a Schl\"afli symbol invariant under reversal.
Building on this, we give a \emph{doubling construction} producing, for every
$m$, a self-dual string group representation of the alternating group $A_{4m+3}$
of rank $2m$, obtained by pushing the rank-$2m$ simplex through an explicit
sign-preserving homomorphism $\Sym(2m+1)\to A_{4m+3}$. Finally, we prove the
\emph{maximal rank theorem}: for $n=4m+3$ with $m\ge 3$, every self-dual string
C-group representation of $A_n$ has rank at most $2m$, strictly below the general
maximum $\lfloor(n-1)/2\rfloor=2m+1$. Thus self-duality --- an external symmetry
--- forces a genuine drop of exactly one in the achievable rank for this infinite
family.
\end{abstract}

\maketitle

\section{Introduction}

Abstract regular polytopes generalize the classical Platonic theory by
abstracting away the geometry and retaining only the combinatorial--algebraic
skeleton. To a regular polytope one associates its automorphism group together
with a distinguished set of involutory generators; the resulting object is a
\emph{string C-group}. Conversely, every string C-group is the automorphism
group of a unique abstract regular polytope. The \emph{rank} of the polytope
equals the number of generators and plays the role of dimension.

A central line of research determines, for a fixed family of groups, the highest
rank of an abstract regular polytope the family supports. For $\Sym(n)$ the
answer is $n-1$, realized by the simplex. For the alternating groups $A_n$ the
maximal rank was determined by Fernandes and Leemans to be $\lfloor(n-1)/2\rfloor$
for $n$ large enough.

Among regular polytopes, the \emph{self-dual} ones are of particular interest. A
natural refinement asks: what is the maximal rank of a self-dual string C-group
representation of a given group? This paper answers that for $A_n$ with
$n\equiv 3\pmod 4$. Writing $n=4m+3$, the general maximal rank is $2m+1$. Our
main results are achievability of rank $2m$ (Theorem~\ref{thm:achieve}) and
optimality, namely the impossibility of rank $2m+1$ (Theorem~\ref{thm:max}). The
conceptual core is the palindrome theorem (Theorem~\ref{thm:palindrome}).

All results have been formalized and machine-checked.

\section{String group representations}

Throughout, $G$ denotes a group and $r\in\mathbb{N}$ a rank. We index generators
by $\Fin r=\{0,\dots,r-1\}$ and write $\rev(i)=r-1-i$ for the reversal involution.

\begin{definition}[String group representation]
A \textbf{string group representation} of $G$ of rank $r$ is a function
$\rho:\Fin r\to G$ such that:
\begin{itemize}
\item \emph{(Involution)} $\rho_i\,\rho_i=1$ for all $i$;
\item \emph{(String condition)} for all $i,j$ with $i<j-1$,
$\rho_i\,\rho_j=\rho_j\,\rho_i$.
\end{itemize}
\end{definition}

A \emph{string C-group representation} additionally satisfies the
\emph{intersection property}
\[
\langle\rho_i:i\in I\rangle\cap\langle\rho_i:i\in J\rangle
=\langle\rho_i:i\in I\cap J\rangle
\qquad\text{for all }I,J\subseteq\Fin r.
\]
Our achievability construction produces an honest string group representation;
our optimality theorem treats the intersection property abstractly, importing its
consequences as explicit hypotheses.

\begin{definition}[Period matrix]
The \textbf{period matrix} of $S$ is
$\period_S(i,j)=\ord(\rho_i\,\rho_j)\in\mathbb{N}$.
\end{definition}

\begin{theorem}[Symmetry; \texttt{period\_swap}]\label{thm:swap}
For all $i,j$, $\period_S(i,j)=\period_S(j,i)$.
\end{theorem}

\begin{proof}[Proof sketch]
Each generator is an involution, so $\rho_i^{-1}=\rho_i$ and hence
$(\rho_i\rho_j)^{-1}=\rho_j^{-1}\rho_i^{-1}=\rho_j\rho_i$. An element and its
inverse share the same order, so $\ord(\rho_i\rho_j)=\ord(\rho_j\rho_i)$.
\end{proof}

\begin{proposition}[Diagonal; \texttt{period\_self}]
$\period_S(i,i)=1$ for all $i$, since $\rho_i\rho_i=1$ and $\ord(1)=1$.
\end{proposition}

\begin{definition}[Schl\"afli symbol]
The \textbf{Schl\"afli symbol} is the first sub-diagonal of the period matrix,
indexed by $k\in\Fin(r-1)$:
\[
\schlafli_S(k)=\period_S(k,k+1)=\ord(\rho_k\,\rho_{k+1}).
\]
\end{definition}

\section{Duality and the palindrome theorem}

\begin{definition}[Dual; self-duality]
The \textbf{dual} of $S$ is $(S^{\ast})_i=\rho_{\rev(i)}$; it is again a string
group representation, and $(S^{\ast})^{\ast}=S$. The representation $S$ is
\textbf{self-dual} if there is $\alpha\in\Aut(G)$ with
$\alpha(\rho_i)=\rho_{\rev(i)}$ for all $i$.
\end{definition}

\begin{theorem}[Reversal-invariance; \texttt{period\_rev\_of\_selfDual}]\label{thm:revinv}
If $S$ is self-dual, then for all $i,j$,
$\period_S(\rev(i),\rev(j))=\period_S(i,j)$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $\alpha$ witness self-duality. Automorphisms preserve order, and
$\alpha(\rho_i\rho_j)=\rho_{\rev(i)}\rho_{\rev(j)}$, so
$\ord(\rho_i\rho_j)=\ord(\rho_{\rev(i)}\rho_{\rev(j)})$.
\end{proof}

\begin{theorem}[Palindrome theorem; \texttt{schlafli\_palindrome}]\label{thm:palindrome}
If $S$ is self-dual then its Schl\"afli symbol is a palindrome:
$\schlafli_S(\rev(k))=\schlafli_S(k)$ for all $k\in\Fin(r-1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Unfold $\schlafli_S(\rev(k))=\period_S(\rev(k),\rev(k)+1)$; use
$\rev(k)+1=\rev(k-1)$ and Theorem~\ref{thm:revinv} to obtain
$\period_S(k-1,k)$, which by Theorem~\ref{thm:swap} equals
$\period_S(k,k+1)=\schlafli_S(k)$.
\end{proof}

An external symmetry of $G$ forces an internal numerical symmetry of the
Schl\"afli sequence.

\section{Functoriality}

\begin{definition}[Push-forward; \texttt{map}]
For a homomorphism $\varphi:G\to H$ and a representation $S$ of $G$, the
\textbf{push-forward} $\varphi_{\ast}S$ has generators
$(\varphi_{\ast}S)_i=\varphi(\rho_i)$. Involution and string conditions are
preserved because $\varphi$ respects products.
\end{definition}

\begin{theorem}[Transfer of inner self-duality; \texttt{map\_selfDual\_of\_inner}]\label{thm:transfer}
If $S$ is self-dual through conjugation by an inner element $w\in G$, i.e.
$w\rho_i w^{-1}=\rho_{\rev(i)}$ for all $i$, then for any homomorphism
$\varphi:G\to H$ the push-forward $\varphi_{\ast}S$ is self-dual, witnessed by
conjugation by $\varphi(w)$.
\end{theorem}

\begin{proof}[Proof sketch]
With $\alpha=\mathrm{conj}_{\varphi(w)}$,
$\alpha(\varphi(\rho_i))=\varphi(w\rho_i w^{-1})=\varphi(\rho_{\rev(i)})
=(\varphi_{\ast}S)_{\rev(i)}$.
\end{proof}

\section{The simplex and the doubling construction}

\begin{definition}[Simplex; \texttt{simplex}]
The \textbf{rank-$r$ simplex representation} of $\Sym(\Fin(r+1))$ has generators
the adjacent transpositions $\rho_i=(i,\,i+1)$, $i=0,\dots,r-1$. Non-adjacent
transpositions have disjoint supports and commute.
\end{definition}

\begin{theorem}[Self-duality of the simplex; \texttt{simplex\_selfDual}]\label{thm:simplex}
The simplex is self-dual through conjugation by the reversal permutation
$w=\rev$ of $\Fin(r+1)$ (i.e.\ $x\mapsto r-x$):
$\rev\cdot(i,i+1)\cdot\rev^{-1}=\rho_{\rev(i)}$. This witness is inner, so
Theorem~\ref{thm:transfer} applies.
\end{theorem}

\begin{remark}
Overlapping adjacent transpositions multiply to a $3$-cycle:
$(i,i{+}1)(i{+}1,i{+}2)=(i,i{+}1,i{+}2)$ of order $3$. Hence the simplex has
Schl\"afli symbol $\{3,3,\dots,3\}$, a palindrome consistent with
Theorem~\ref{thm:palindrome}.
\end{remark}

\begin{definition}[Doubling; \texttt{dblHom}, \texttt{dblPerm}, \texttt{dblAlt}]
For $\sigma\in\Sym(\Fin(2m+1))$ set $\mathrm{dbl}(\sigma)=\sigma\oplus\sigma\oplus 1$
acting on $\Fin(2m+1)\sqcup\Fin(2m+1)\sqcup\Fin 1$. This is a homomorphism; the
carrier has cardinality $4m+3$, so a chosen bijection transports it to
$\mathrm{dblPerm}:\Sym(\Fin(2m+1))\to\Sym(\Fin(4m+3))$.
\end{definition}

\begin{lemma}[Doubling is even; \texttt{dblPerm\_sign}]\label{lem:sign}
$\sgn(\mathrm{dblPerm}(\sigma))=1$ for all $\sigma$.
\end{lemma}

\begin{proof}[Proof sketch]
Sign is conjugation-invariant and multiplicative over block sums, so
$\sgn(\sigma\oplus\sigma\oplus 1)=\sgn(\sigma)^2=1$.
\end{proof}

Hence $\mathrm{dblPerm}$ corestricts to $\mathrm{dblAlt}:\Sym(\Fin(2m+1))\to A_{4m+3}$.

\begin{theorem}[Achievability; \texttt{A4m3\_selfDual\_rank2m}]\label{thm:achieve}
For every $m\in\mathbb{N}$, $A_{4m+3}$ admits a self-dual string group
representation of rank $2m$, namely
$S=(\mathrm{dblAlt})_{\ast}(\mathrm{simplex}(2m))$.
\end{theorem}

\begin{proof}[Proof sketch]
$S$ is a valid rank-$2m$ representation by functoriality. By
Theorem~\ref{thm:simplex} the simplex is self-dual through the inner element
$\rev$, and by Theorem~\ref{thm:transfer} the push-forward inherits self-duality,
witnessed by $\mathrm{dblAlt}(\rev)$.
\end{proof}

\section{The maximal rank theorem}

For $n=4m+3$ the general maximal rank of a string C-group representation of $A_n$
is $\lfloor(n-1)/2\rfloor=2m+1$ (Fernandes--Leemans). We import this and the
top-rank shape statement as hypotheses.

\begin{theorem}[Maximal self-dual rank; \texttt{max\_selfDual\_rank\_A4m3}]\label{thm:max}
Let $m\ge 3$ and $n=4m+3$. Let $S$ be a self-dual string C-group representation
of $A_n$ of rank $r$, and assume:
\begin{itemize}
\item \emph{(\texttt{hbound})} $r\le 2m+1$;
\item \emph{(\texttt{hmaxShape})} if $r=2m+1$ then the Schl\"afli symbol of $S$
is not a palindrome.
\end{itemize}
Then $r\le 2m$.
\end{theorem}

\begin{proof}[Proof sketch]
If $r<2m+1$ then $r\le 2m$. Otherwise $r=2m+1$ by antisymmetry. By
Theorem~\ref{thm:palindrome} the Schl\"afli symbol of the self-dual $S$ is a
palindrome, contradicting \texttt{hmaxShape}. Hence $r=2m+1$ is impossible.
\end{proof}

Combining Theorems~\ref{thm:achieve} and~\ref{thm:max}: for $n=4m+3$ with
$m\ge 3$, the maximal rank of a self-dual string C-group representation of $A_n$
is exactly $2m$, one below the general maximum $2m+1$.

\subsection{On the structural hypothesis}
At rank $r=2m+1$ the Schl\"afli symbol has length $2m$, even, so the reversal is
fixed-point free and pairs each position with a distinct partner. The central
involution forced at the top of the rank tower has a support parity incompatible
with equality across every mirror pair, breaking palindromicity. The residue
$n\equiv 1\pmod 4$ instead gives an odd top length with a stable center,
suggesting no rank drop there.

\section{Discussion and future work}

\begin{conjecture}[Unconditional bound]
Both \texttt{hbound} and \texttt{hmaxShape} can be proved inside the framework
once the intersection property is formalized, giving an unconditional
$\mathrm{rank}\le 2m$.
\end{conjecture}

\begin{conjecture}[Odd/even corank law]
The maximal self-dual rank equals $\lfloor(n-1)/2\rfloor-1$ exactly when
$n\equiv 3\pmod 4$, and equals $\lfloor(n-1)/2\rfloor$ when $n\equiv 1\pmod 4$.
\end{conjecture}

\begin{conjecture}[Doubling is universal]
Every self-dual rank-$2m$ representation of $A_{4m+3}$ is equivalent to one
produced by doubling a self-dual rank-$2m$ simplex-like representation.
\end{conjecture}

\begin{conjecture}[Palindromes characterize self-duality]
A representation of a centreless group is self-dual iff its full period matrix is
reversal-symmetric.
\end{conjecture}

\section{Conclusion}
We built the algebra of string group representations, proved that self-duality
forces a palindromic Schl\"afli symbol, constructed self-dual rank-$2m$
representations of $A_{4m+3}$ by doubling the simplex, and showed rank $2m+1$ is
unreachable under self-duality for $m\ge 3$. The maximal self-dual rank of
$A_{4m+3}$ is exactly $2m$ --- one short of the general maximum.

\end{document}

