function PeriodMatrixAndPalindrome(rho[0..r-1]):
    for i in 0..r-1:
        for j in 0..r-1:
            g <- compose(rho[i], rho[j])
            P[i][j] <- order(g)            # lcm of cycle lengths of g
    schlafli <- [ P[k][k+1] for k in 0..r-2 ]
    palindrome <- (schlafli == reverse(schlafli))
    return P, schlafli, palindrome

function Double(sigma, m):
    block <- 2m+1 ; n <- 4m+3
    p <- identity(n)
    for i in 0..block-1:
        p[i] <- sigma[i]                 # first copy
        p[block+i] <- block + sigma[i]   # second copy
    return p                              # last point fixed

function DoubledSimplex(m):
    gens <- [ Double((i,i+1), m) for i in 0..2m-1 ]
    assert all sign(g) == +1 for g in gens   # lies in A_{4m+3}
    return gens

